-- ============================================================================
-- V12: 商品图片按品类对应（替换 picsum 随机风景图）
--   每类一张品类 emoji 渐变插画（URL-encoded SVG data URI，零外链依赖）
--   original_image_url 保留原值可追溯
-- ============================================================================

UPDATE product
SET image_url = CASE category
  WHEN 'PHONE' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23dbe7ff'/%3E%3Cstop offset='1' stop-color='%23f3e8ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%93%B1%3C/text%3E%3C/svg%3E'
  WHEN 'LAPTOP' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23d6e6fb'/%3E%3Cstop offset='1' stop-color='%23e8f0d8'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%92%BB%3C/text%3E%3C/svg%3E'
  WHEN 'APPLIANCE' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23d2f1ec'/%3E%3Cstop offset='1' stop-color='%23e0f6e9'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%A7%BA%3C/text%3E%3C/svg%3E'
  WHEN 'CLOTHING' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23ffe3e3'/%3E%3Cstop offset='1' stop-color='%23ffeed9'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%91%95%3C/text%3E%3C/svg%3E'
  WHEN 'BEAUTY' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23ffe0ec'/%3E%3Cstop offset='1' stop-color='%23ffeef3'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%92%84%3C/text%3E%3C/svg%3E'
  WHEN 'FOOD' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23ffe6d6'/%3E%3Cstop offset='1' stop-color='%23fff3d6'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%8D%8E%3C/text%3E%3C/svg%3E'
  WHEN 'MATERNAL' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23ffeed6'/%3E%3Cstop offset='1' stop-color='%23e3f2ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%A7%B8%3C/text%3E%3C/svg%3E'
  WHEN 'SPORTS' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23e2f4d8'/%3E%3Cstop offset='1' stop-color='%23d8f0f4'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%E2%9A%BD%3C/text%3E%3C/svg%3E'
  WHEN 'BOOK' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23e8e2ff'/%3E%3Cstop offset='1' stop-color='%23dce7ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%93%9A%3C/text%3E%3C/svg%3E'
  WHEN 'HOME' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23e6ecff'/%3E%3Cstop offset='1' stop-color='%23f6e8ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%9B%8B%EF%B8%8F%3C/text%3E%3C/svg%3E'
  WHEN 'JEWELRY' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23d9f2f7'/%3E%3Cstop offset='1' stop-color='%23e5e0ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%92%8E%3C/text%3E%3C/svg%3E'
  WHEN 'BAGS' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23f0e6d8'/%3E%3Cstop offset='1' stop-color='%23e8ffd9'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%8E%92%3C/text%3E%3C/svg%3E'
  WHEN 'SHOES' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23e0f0ff'/%3E%3Cstop offset='1' stop-color='%23ffe9e0'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%91%9F%3C/text%3E%3C/svg%3E'
  WHEN 'PET' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23fff0d9'/%3E%3Cstop offset='1' stop-color='%23ffdfe3'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%90%BE%3C/text%3E%3C/svg%3E'
  WHEN 'HEALTH' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23d9f7e8'/%3E%3Cstop offset='1' stop-color='%23e0f4ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%A9%BA%3C/text%3E%3C/svg%3E'
  WHEN 'CAR' THEN 'data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='600' height='600'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23e0e6f2'/%3E%3Cstop offset='1' stop-color='%23e8ffe0'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='600' height='600' fill='url(%23g)'/%3E%3Ccircle cx='300' cy='300' r='190' fill='rgba(255,255,255,0.55)'/%3E%3Ctext x='300' y='318' font-size='300' text-anchor='middle' dominant-baseline='middle'%3E%F0%9F%9A%97%3C/text%3E%3C/svg%3E'
  ELSE image_url
END
WHERE deleted = 0;
